Throughout we consider the polynomial optimization problem, asking to minimize a polynomial $p$ over the unit sphere $\oS^{n-1}$, i.e., to compute
\begin{align}\label{eqpmin}
p_{\min}=\min_{x\in \oS^{n-1}}p(x)=\min\{p(x): x\in \R^n, \|x\|_2=1\}.
\end{align}
Therein, $p\in \R[x]=\R[x_1,\ldots,x_n]$ is an $n$-variate polynomial of degree $2d$. In other words,

 We now recall several notions of symmetry for tensors. \tcolblue{In Appendix \ref{appendix-example} we illustrate some   of these notions on examples.}

Permutations $\sigma\in \MFS_r$ act on $[n]^r$ and thus on $r$-tensors, in the following way.
For $\ui\in [n]^r$, set $\ui^\sigma=(i_{\sigma(1)},\ldots, i_{\sigma(r)})$ and, for  $v\in (\K^n)^{\ot r}$, define $v^\sigma$ as the $r$-tensor with entries $(v^\sigma)_{\ui}= v_{\ui^\sigma}$ for $\ui\in [n]^r$.
Then, $v$ is said to be a {\em symmetric tensor} if $v^\sigma=v$ for all $\sigma\in \MFS_r$, and $S^r(\K^n)$ denotes the space of symmetric $r$-tensors on $\K^n$. We let $\Pi_r$ denote the projection from the space $(\K^n)^{\ot r}$ to the symmetric subspace $S^r(\K^n)$. Concretely, we have 
\begin{align}\label{eqPir}
\Pi_r=\frac{1}{r!}\sum_{\sigma\in \MFS_r} P_\sigma,
\end{align}
where $P_\sigma$ is the square matrix indexed by $[n]^r\times [n]^r$, with entries 
$(P_\sigma)_{\ui, \uj}=1$ if $\uj=\ui^\sigma$ and 0 otherwise, for $\ui,\uj\in [n]^r$.

Consider a  matrix $M$ indexed by the set $[n]^r\times [n]^r$, so that $M$ represents an endomorphism from $(\K^n)^{\ot r}$ to $(\K^n)^{\ot r}$. Then, any permutation $\sigma\in \MFS_r$  induces naturally a permutation of  the columns (and rows) of $M$. 

\begin{definition}[Doubly symmetric matrix]\label{defdoublesymmetric}
A matrix $M\in \K^{[n]^r\times [n]^r}$  is called  {\em $r$-column symmetric} (resp., {\em $r$-row symmetric}) if $M\Pi_r =M$ (resp., $\Pi_rM=M$). If $M$ is complex Hermitian or real symmetric, then $M$ is $r$-column symmetric if and only if it is $r$-row symmetric, or equivalently if $\Pi_rM\Pi_r=M$, in which case  $M$ is called {\em $ r $-doubly symmetric} (or just {\em doubly symmetric} if $r$ is clear from the context).
\end{definition}


Hermitian doubly symmetric matrices are also known as {\em Bose symmetric} matrices in the quantum information literature. \MoL{The following stronger symmetry property is sometimes needed (it is considered, e.g.,   in \cite{Doherty_Wehner_2013}).}

\begin{definition}[Maximally symmetric matrix]\label{defmaximallysymmetric}
A  matrix $M\in \K^{[n]^r\times [n]^r}$ can be   viewed as  a $2r$-tensor $\vvec(M)\in (\K^n)^{\ot 2r}$, with entries  $\vvec(M)_{\ui\uj} = M_{\ui,\uj}$ for $\ui,\uj\in [n]^r$.
Then, $M$ is said to be {\em maximally symmetric} when $\vvec(M)$ is a symmetric $2r$-tensor.
\end{definition}

\begin{lemma}\label{lem:sos-equiv-gram-matrix}
A polynomial $f$ is a sum of squares if and only if it admits a positive semidefinite representing matrix (then, often called a {\em Gram matrix} of $f$).
\end{lemma}

\begin{definition} \label{defGramtensor}
	Let $f\in R_{2d}$. A symmetric matrix $G$ indexed by $[n]^d$ is called a {\em tensor-indexed representing matrix} of  $ f $ if the following polynomial identity holds:
	\begin{align*}
		f = (x^{\otimes d})^{T}G x^{\otimes d} = \langle G, (x x^{T})^{\otimes d} \rangle. 
	\end{align*}
\end{definition}

