We introduce the spectral hierarchy of \johnstonlovitz{} \cite{Johnston_Lovitz_Vijayaraghavan_2023}. 
Let $p\in R_{2d}$ and recall the matrices $Q(p)$   and $M$ from (\ref{eqQpM}). For an integer $ r\ge d $, define the matrices 
\begin{align}\label{eqQrpM}
	Q_r(p) = \Pi_{r}(Q(p) \otimes I_n^{\otimes (r-d)})\Pi_{r}, \\
	M_r= \Pi_{r}(M \otimes I_n^{\otimes (r-d)})\Pi_{r}. 
\end{align}

\begin{definition}
	The spectral bound $\spec_r(p)$  is defined by any of the following equivalent programs:
	\begin{align}
		\spec_r(p)& =\max_{\nu\in\R} \{ \nu: Q_r(p)-\nu M_r\succeq 0\},\label{eqnu1} \\
		& = \min_{v\in S^r(\R^n) } \{v^T Q_r(p)v: v^T M_rv=1\}, \label{eqnu2}\\
		& = \min_{X } \{\langle Q_r(p), X\rangle: X \  r\text{-doubly symmetric},\ X\succeq 0,\ \langle M_r,X\rangle =1\}.\label{eqnu3}
	\end{align}
\end{definition}

We start by picking a  quartic form  in four variables that is nonnegative but not a sum of squares.
A concrete example is given by the \emph{Choi-Lam form} $ p_{CL} $, 
\begin{align}\label{eqpCL}
	p_{CL}(x) = x_1^2x_2^2+x_1^2x_3^2+ x_2^2x_3^2 + x_4^4 -4 x_1x_2x_3x_4.
\end{align}

If, as a 4-variate polynomial,  $ p_{CL} $ is represented by a matrix $ Q^{(4)} \in \R^{[4]^2\times [4]^2} $, then, as a 5-variate polynomial in   $ \underline{x} = (x,u) $, it is represented by the matrix 
\begin{align}\label{eqmatQ}
	\begin{pmatrix}
		Q^{(4)} & 0\\
		0^{T} & 0
	\end{pmatrix} \in  \R^{[5]^2\times [5]^2}.
\end{align}

Note that the same holds   for the maximally symmetric representations of $p_{CL}$  in four variables and of $p $ as a polynomial in five variables: 
\begin{align}\label{eqmatMQ}
	\maxsym(p)  = \begin{pmatrix}
		\maxsym(p_{CL}) & 0\\
		0^{T} & 0
	\end{pmatrix}.
\end{align}
The reason is again that $ p $ is only supported on monomials, which do not depend on the fifth variable $ u $.

\begin{theorem}\label{thm:lower-bound-spectral}
	Let $\spec_r(p)$ denote the spectral bound of order $r$ for the Choi-Lam form $p \in \R[x_1,x_2,x_3,x_4,u]$. Then, we have	$p_{\min}=0$ and $\spec_r(p)=\Omega(1/r^2)$.
\end{theorem}

\begin{proof}
	Let the variables be ordered as $ \underline{x} = (x,u)$, where $ x = (x_1,\ldots,x_4) $ and  $ u $ is the fifth variable. Let $r\ge 2$. Set $ s = x_1^2  + x_2^2+x_3^2 + x_4^2 + u^2 $ and 
	\begin{align}\label{eqmats}
	\begin{split}
	 & Q :=   \maxsym(p),\quad  M := \maxsym(s^2), \\
	 &  Q_r := \Pi_r (Q\otimes I_5^{\otimes (r-2)}) \Pi_r,\quad  M_r :=  \Pi_r (M\otimes I_5^{\otimes (r-2)}) \Pi_r.
	\end{split}
	\end{align} 
	So, $Q$ has the block-form as in (\ref{eqmatQ}), (\ref{eqmatMQ}), where $Q^{(4)} :=  \MaxSym(p_{CL}) \in \R^{[4]^2 \times [4]^2} $ and the remaining blocks are filled by zeros. As in (\ref{eqPir}),  $\Pi_2\in \R^{[5]^2\times [5]^2}$ denotes the projection onto the symmetric subspace $S^2(\R^5)$.	The space $\R^{[4]^2}$ can be seen as a subspace of $\R^{[5]^2}$ corresponding to the first four variable indices. Let us write $ \Pi_2^{(4)} \in \R^{[4]^2 \times [4]^2} $ for the restriction of $ \Pi_2$ to the subspace $ \R^{[4]^2} $. 

	Recall  $\spec_r=\spec_r(p)$ for short. By the definition, we have $\spec_r\le p_{\min}=0$ and 
	\begin{align*}
		Q_r + |\spec_r| M_r = \Pi_r ((Q+ |\spec_r|M) \otimes I_5^{\otimes (r-2)}) \Pi_r \succeq 0.
	\end{align*}
	By using  $ M\preceq \lambda_{\max}(M) I_5^{\otimes 2} $, we obtain that 
	\begin{align*}
		G_r :=  \Pi_r ((Q+ \lambda_{\max}(M)|\spec_r|I_5^{\otimes 2}) \otimes I_5^{\otimes (r-2)}) \Pi_r \succeq 0.
	\end{align*}
	In particular, every principal submatrix of $ G_r $ is positive semidefinite. We will now examine \tcolblue{in detail} the following principal submatrix 
	\begin{align}\label{eqmatH}
		H:= ((G_r)_{(i_1,i_2,5,\ldots,5), (j_1,j_2,5,\ldots,5)})_{i_1,i_2,j_1,j_2 \in \{1,\ldots,4\}} \in \R^{[4]^2\times [4]^2}
	\end{align}
	of $ G_r $, where the first two row indices $ i_1, i_2 $ and the first two column indices $ j_1,j_2 $ each range from $ 1 $ to $ 4 $, while the other $ r-2 $ row and column indices are set equal to $ 5 $.


	Recall the notation $ \underline{i}^{\sigma} := (i_{\sigma(1)},\ldots,i_{\sigma(r)}) $ for any $\sigma\in \MFS_r$. For $\ui,\uj\in [5]^r$, using (\ref{eqPir}), we may expand 
	\begin{align*}
		(G_r)_{\underline{i},\underline{j}} = \left(\frac{1}{r!}\right)^2 \sum_{\sigma \in \mathfrak{S}_{r}}\sum_{\tau \in \mathfrak{S}_{r}}  (Q \otimes I_5^{\otimes (r-2)} + \lambda_{\max}(M)|\spec_r|I_5^{\otimes r})_{\underline{i}^{\sigma}, \underline{j}^{\tau}}.
	\end{align*}
	In order to compute the submatrix $ H $, we set the last $ r-2 $ indices of both $ \underline{i} $ and $ \underline{j} $ equal to $ 5 $ and the other two indices not equal to $ 5 $. Hence, on the right hand side, we have to count how many permutations ``survive'' when we do this, in the sense of giving a nonzero contribution to $ H $. 
	We may write 
	\begin{align}\label{eqmatH2}
	 H = A + \lambda_{\max}(M)|\spec_r|B,
	 \end{align}
	  where $ A $ is the contribution arising from $ Q \otimes I_5^{\otimes (r-2)} $ and $ B $ is the contribution from $ I_5^{\otimes r}  $. Since $ I_5^{\otimes r}  $ is diagonal, the only nonzero entries of $ B $ are at indices of the form $ (i_1i_2,i_1i_2) $ and $ (i_1i_2,i_2i_1) $. 
	For later use, notice that $ (\Pi_{2})_{i_1i_2,i_1i_2} = \frac{1}{2} $ if $ i_1\ne i_2 \in [4]$, and $(\Pi_{2})_{i_1i_1,i_1i_1} = 1 $ for $i_1\in [4]$. 
	We now calculate the matrix $B$: for $i_1,i_2\in [4]$, 
	\begin{align*}
		B_{i_1i_2,i_1i_2} &= B_{i_1i_2,i_2i_1} = \frac{1}{(r!)^2} \sum_{\sigma \in \mathfrak{S}_{r}}\sum_{\tau \in \mathfrak{S}_{r}}  (I_5^{\otimes r})_{(i_{1},i_{2},5,\ldots,5)^{\sigma}, (i_{1},i_{2},5,\ldots,5)^{\tau}}\\
		&= 2(\Pi_{2})_{i_1i_2,i_1i_2} \frac{(r-2)!}{(r!)^2} \sum_{\sigma \in \mathfrak{S}_{r}}  (I_5^{\otimes r})_{(i_{1},i_{2},5,\ldots,5)^{\sigma}, (i_{1},i_{2},5,\ldots,5)^{\sigma}}\\
		&= 2(\Pi_{2})_{i_1i_2,i_1i_2}\frac{(r-2)!}{r!} =  \binom{r}{2}^{-1} (\Pi_2)_{i_1i_2,i_1i_2}. 
	\end{align*}	
	Here, in the second line, we   used the fact that $ I_n^{\otimes r} $ is diagonal and that the row and column indices are equal if and only if $ (i_{\sigma(1)},i_{\sigma(2)}) = (i_{\tau(1)},i_{\tau(2)}) $. 
	Given any permutation $ \sigma \in \mathfrak{S}_r$, there are $ (r-2)! $ permutations $ \tau \in \mathfrak{S}_r $ with this property if $ i_1\ne i_2 $, and $ 2(r-2)! $ permutations $ \tau $ with this property if $ i_1 = i_2 $. Hence, there are $ 2(r-2)!(\Pi_{2})_{i_1i_2,i_1i_2} $ permutations $ \tau $ with this property for any given $ \sigma $. 
	In the third line, we used the fact that all diagonal entries of $ I_n^{\otimes r} $ are equal to $ 1 $, so the sum evaluates to $ r! $.  
	Summarized, we conclude that $ B = \binom{r}{2}^{-1} \Pi_2^{(4)} $. 
	Now, let us calculate $ A $: for $i_1,i_2,j_1,j_2\in [4]$,
	\begin{align*}
		A_{i_1i_2,j_1j_2} = \frac{1}{(r!)^2} \sum_{\sigma \in \mathfrak{S}_{r}}\sum_{\tau \in \mathfrak{S}_{r}}  (Q\otimes I_5^{\otimes r-2})_{(i_{1},i_{2},5,\ldots,5)^{\sigma}, (j_{1},j_{2},5,\ldots,5)^{\tau}}.
	\end{align*}
	Recall that $ Q_{i,5} = 0 $ if $ i\in \{1,\ldots,4\} $. Therefore, the only nonzero contributions come from permutations $ \sigma $ and $ \tau $, which keep all 5-indices `to the right', i.e., at the last $r-2$ positions. There are $ 2(r-2)! $ permutations $ \sigma $ and $ 2(r-2)! $ permutations $ \tau $ with this property. They may be written as $ \sigma = \sigma_2\circ \sigma_{r-2} $ and $ \tau =  \tau_2\circ \tau_{r-2}$, respectively, with $ \sigma_2, \tau_2 \in \mathfrak{S}_2 $ and $ \sigma_{r-2}, \tau_{r-2} \in \mathfrak{S}_{r-2} $.
	So, we obtain  
	\begin{align*}
		A_{i_1i_2,j_1j_2} &= \frac{((r-2)!)^2}{(r!)^2} \sum_{\sigma_2, \tau_2 \in \mathfrak{S}_{2}} (Q\otimes I_n^{\otimes r-2})_{(i_{\sigma_2(1)},i_{\sigma_2(2)},5,\ldots,5), (j_{\tau_2(1)},j_{\tau_2(2)},5,\ldots,5)}.\\
		&= \left(\frac{(r-2)!}{r!}\right)^2 \sum_{\sigma_2, \tau_2 \in \mathfrak{S}_{2}} Q_{i_{\sigma_2(1)}i_{\sigma_2(2)}, j_{\tau_2(1)}j_{\tau_2(2)}}.\\
		&= \binom{r}{2}^{-2} Q_{i_1i_2,j_1j_2}.
	\end{align*}
	In the first line, we used the fact that the $ (r-2)!^2 $ permutations of the 5-indices all yield the same indices. In the second line, we used that $ (I_n^{\otimes r-2})_{5\ldots5,5\ldots5} = 1 $. In the third line, we used that $ Q $ is maximally symmetric, hence in particular doubly symmetric. Thus, the $ 2^2 = 4 $ permutations of the non-5 indices all yield the same entry. Summarizing, we have shown  
	$$ A = \binom{r}{2}^{-2}Q^{(4)},\quad  B = \binom{r}{2}^{-1}\Pi_{2}^{(4)}.
	$$
	 We conclude that the   matrix $ H $ from (\ref{eqmatH})-(\ref{eqmatH2}) can be expressed as
	\begin{align*}
		\binom{r}{2}^{2}  H = Q^{(4)} + \lambda_{\max}(M)|\spec_r|\binom{r}{2}\Pi_{2}^{(4)}. 
	\end{align*}
	Now, we use that $H\succeq 0$ and $\begin{pmatrix} \Pi_2^{(4)} & 0 \\ 0^{T} & 0 \end{pmatrix} \preceq I_5^{\otimes 2} \preceq \frac{1}{\lambda_{\min}(M)} M $ to obtain  
	\begin{align*}
		0\preceq \binom{r}{2}^{2} \begin{pmatrix} H & 0 \\ 0^{T} & 0 \end{pmatrix}  \preceq Q + |\spec_r|\frac{\lambda_{\max}(M)}{\lambda_{\min}(M)} \binom{r}{2} M. 
	\end{align*}
	By definition, $ |\spec_2| $ is the smallest value such that 
	\begin{align*}
		Q + |\spec_2| M \succeq 0. 
	\end{align*}
	Hence, it follows that 
	\begin{align*}
		 |\spec_r|\frac{\lambda_{\max}(M)}{\lambda_{\min}(M)} \binom{r}{2} \ge |\spec_2|, \:\: \text{ and thus }\:\: 	|\spec_r| \ge \frac{\lambda_{\min}(M)}{\lambda_{\max}(M)} |\spec_2|\binom{r}{2}^{-1} = \Omega\left(\frac{1}{r^2}\right),		 
	\end{align*}
\tcolblue{using the fact that $M\succ 0$ \cite{Johnston_Lovitz_Vijayaraghavan_2023} and $|\spec_2|>0$ as $p$ is not sos.} 
\end{proof}

